'use strict';
const TRASH_KINDS={project:'Dự án',task:'Công việc',check:'Mục checklist',note:'Ghi chú',image:'Hình ảnh',video:'Video',audio:'Âm thanh',document:'Tệp khác'};
const recycleSelection=new Set();
let recycleFiles=[],recycleOwner='',recycleLoading=false,recycleError='',recycleFilter='all',recycleView=localRead('zen-trash-layout')||'grid',recyclePending=0;
function trashFileKind(f){const name=f.name.toLowerCase();return f.mime?.startsWith('image/')||/\.(png|jpe?g|gif|webp|svg|heic)$/.test(name)?'image':f.mime?.startsWith('video/')||/\.(mp4|webm|mov)$/.test(name)?'video':f.mime?.startsWith('audio/')||/\.(mp3|wav|ogg|m4a)$/.test(name)?'audio':'document';}
function recycleItems(){return [...(data.trash||[]).map(x=>({...x,key:'data:'+x.id,source:'data',kind:x.kind,at:x.at})),...recycleFiles.map(f=>({...f,key:f.source+':'+f.id,kind:trashFileKind(f),at:f.deleted}))].sort((a,b)=>b.at-a.at);}
function recycleMarkup(){const all=recycleItems(),counts={};for(const i of all)counts[i.kind]=(counts[i.kind]||0)+1;const items=all.filter(i=>recycleFilter==='all'||recycleFilter==='files'?recycleFilter==='all'||i.source!=='data':i.kind===recycleFilter);return '<section class="recycle-overview"><div><strong>'+all.length+'</strong><span>Mục trong Thùng rác</span></div><div><strong>'+recycleFiles.length+'</strong><span>Tệp đính kèm · '+formatSize(recycleFiles.reduce((n,f)=>n+f.size,0))+'</span></div><div><strong>'+(data.trash||[]).length+'</strong><span>Dự án, ghi chú và công việc</span></div></section><div class="recycle-toolbar"><div class="recycle-filters"><button class="btn '+(recycleFilter==='all'?'primary':'')+'" data-trash-filter="all">Tất cả · '+all.length+'</button><button class="btn" data-trash-filter="files">Tệp · '+recycleFiles.length+'</button>'+Object.entries(counts).map(([kind,count])=>'<button class="btn '+(recycleFilter===kind?'primary':'')+'" data-trash-filter="'+kind+'">'+TRASH_KINDS[kind]+' · '+count+'</button>').join('')+'</div><div class="recycle-layout" role="group" aria-label="Kiểu xem Thùng rác"><button class="btn '+(recycleView==='grid'?'primary':'')+'" data-trash-layout="grid" aria-pressed="'+(recycleView==='grid')+'">'+svgIcon('dashboard')+'Lưới</button><button class="btn '+(recycleView==='list'?'primary':'')+'" data-trash-layout="list" aria-pressed="'+(recycleView==='list')+'">'+svgIcon('tasks')+'Danh sách</button></div></div>'+(recycleLoading?'<p role="status" class="subtext">Đang cập nhật danh sách tệp…</p>':'')+(recycleError?'<p role="alert" class="recycle-error">'+esc(recycleError)+' <button type="button" class="btn" data-trash-refresh>Thử lại</button></p>':'')+'<div class="recycle-selection"><span>'+recycleSelection.size+' mục đã chọn</span><button type="button" class="btn danger" data-trash-delete-selected '+(recycleSelection.size?'':'disabled')+'>Xóa đã chọn</button></div><div class="recycle-items '+recycleView+'">'+items.map(i=>'<article class="recycle-item"><label class="recycle-select"><input type="checkbox" data-trash-select="'+esc(i.key)+'" '+(recycleSelection.has(i.key)?'checked':'')+' aria-label="Chọn '+esc(i.name)+'"></label><span class="recycle-symbol">'+svgIcon(i.kind==='project'?'leaf':i.kind==='note'?'notes':i.source==='data'?'tasks':'attach')+'</span><div class="recycle-name"><small>'+TRASH_KINDS[i.kind]+'</small><h3>'+esc(i.name)+'</h3><p>'+new Date(i.at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+'</p><small>'+Math.max(0,30-Math.floor((Date.now()-i.at)/86400000))+' ngày còn lại'+(i.source!=='data'?' · '+formatSize(i.size):'')+'</small></div><div class="recycle-actions"><button class="btn" '+(i.source==='data'?'data-restore-item="'+esc(i.id)+'"':'data-restore-file="'+esc(i.id)+'" data-legacy="'+(i.source==='legacy')+'"')+'>'+svgIcon('versions')+'Khôi phục</button><button class="btn danger" data-trash-delete="'+esc(i.key)+'">'+svgIcon('trash')+'Xóa</button></div></article>').join('')+(!items.length&&!recycleLoading?'<div class="empty">Không có dữ liệu trong nhóm này.</div>':'')+'</div>';}
trashPage=function(){if(recycleOwner!==currentUser?.id){recycleFiles=[];recycleSelection.clear();recycleOwner=currentUser?.id||'';recycleError='';}return heading('KHÔI PHỤC HOẶC DỌN DẸP','Thùng rác','Tự dọn sau 30 ngày. Xóa vĩnh viễn sẽ không thể khôi phục.','<button class="btn danger" data-trash-empty>'+svgIcon('trash')+'Dọn sạch Thùng rác</button>')+'<div id="recycle-content">'+recycleMarkup()+'</div>';};
function paintRecycle(){const node=$('#recycle-content');if(node&&view==='trash')node.innerHTML=recycleMarkup();}
loadTrashFiles=async function(){if(recycleLoading)return;recycleLoading=true;recycleError='';const owner=currentUser?.id,request=++recyclePending;paintRecycle();try{const result=await requestAPI('assets/trash');if(currentUser?.id!==owner||request!==recyclePending)return;recycleFiles=[...(result.files||[]).map(f=>({...f,source:'r2'})),...(result.legacy||[]).map(f=>({...f,source:'legacy'}))];}catch(error){recycleError=error.message;}finally{recycleLoading=false;paintRecycle();}};
async function syncBeforeTrashPurge(owner){
 const deadline=Date.now()+23000;
 while(syncing&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,80));if(currentUser?.id!==owner)throw Error('Phiên đăng nhập đã thay đổi.');}
 if(syncing)throw Error('Đồng bộ đang xử lý. Vui lòng thử lại sau.');
 if(currentUser?.id!==owner)throw Error('Phiên đăng nhập đã thay đổi.');
 if(syncConflict)throw Error('Dữ liệu có xung đột. Mở Cài đặt → Dữ liệu để xử lý trước khi dọn rác.');
 await flushCloud(true);
 while(syncing&&Date.now()<deadline)await new Promise(resolve=>setTimeout(resolve,80));
 if(currentUser?.id!==owner)throw Error('Phiên đăng nhập đã thay đổi.');
 if(dirty)throw Error(!navigator.onLine?'Đang ngoại tuyến. Kết nối mạng rồi thử lại; Thùng rác chưa bị xóa.':'Chưa đồng bộ được dữ liệu. Mở Cài đặt → Đồng bộ ngay để xem chi tiết.');
}
function confirmTrashPurge(key){const all=recycleItems(),selected=key?all.filter(i=>Array.isArray(key)?key.includes(i.key):i.key===key):all;if(!selected.length)return notify('Thùng rác đang trống.');if(recycleLoading||recycleError)return notify('Chờ danh sách tệp tải xong trước khi xóa.');const owner=currentUser?.id;const ids=new Set(selected.filter(i=>i.source==='data').map(i=>i.id)),files=selected.filter(i=>i.source!=='data');modal('<h2>'+ (key?'Xóa vĩnh viễn các mục đã chọn?':'Dọn sạch Thùng rác?')+'</h2><p class="help-copy">'+(selected.length===1?esc(selected[0].name):selected.length+' mục · '+files.length+' tệp đính kèm')+'</p><p class="purge-warning">Thao tác này không thể hoàn tác. Các mục đã chọn sẽ không còn trong Thùng rác.</p><p id="purge-status" role="status"></p>',async()=>{const button=$('#editor-form [type=submit]');button.disabled=true;try{$('#purge-status').textContent='Đang xác nhận đồng bộ…';await syncBeforeTrashPurge(owner);for(let i=0;i<files.length;i+=20){await requestAPI('assets/purge','POST',{items:files.slice(i,i+20).map(f=>({source:f.source,id:f.id}))});recycleFiles=recycleFiles.filter(f=>!files.slice(i,i+20).some(x=>x.source===f.source&&x.id===f.id));$('#purge-status').textContent='Đã xử lý '+Math.min(files.length,i+20)+'/'+files.length+' tệp.';}const previousTrash=data.trash;data.trash=(data.trash||[]).filter(i=>!ids.has(i.id));if(save()===false){data.trash=previousTrash;throw Error('Không lưu được thay đổi trên thiết bị.');}undoData=null;$('#purge-status').textContent='Đã dọn trên máy · đang đồng bộ…';await syncBeforeTrashPurge(owner);if(dirty)throw Error('Chưa gửi được thay đổi. Bản trên máy đã lưu; kết nối lại để hoàn tất đồng bộ.');selected.forEach(i=>recycleSelection.delete(i.key));$('#editor').close();render();notify('Đã xóa vĩnh viễn các mục đã chọn.');}catch(error){$('#purge-status').textContent=error.message;paintRecycle();}finally{button.disabled=false;}});const submit=$('#editor-form [type=submit]');submit.textContent=key?'Xóa vĩnh viễn':'Dọn sạch Thùng rác';submit.classList.add('danger');}
document.addEventListener('click',e=>{const del=e.target.closest('[data-trash-delete]'),empty=e.target.closest('[data-trash-empty]'),filter=e.target.closest('[data-trash-filter]'),layout=e.target.closest('[data-trash-layout]');if(del)confirmTrashPurge(del.dataset.trashDelete);if(empty)confirmTrashPurge();if(filter){recycleFilter=filter.dataset.trashFilter;paintRecycle();}if(layout){recycleView=layout.dataset.trashLayout;localWrite('zen-trash-layout',recycleView);paintRecycle();}if(e.target.closest('[data-trash-refresh]'))loadTrashFiles();});

document.addEventListener('change',e=>{const input=e.target.closest('[data-trash-select]');if(!input)return;if(input.checked)recycleSelection.add(input.dataset.trashSelect);else recycleSelection.delete(input.dataset.trashSelect);paintRecycle();});
document.addEventListener('click',e=>{if(e.target.closest('[data-trash-delete-selected]')&&recycleSelection.size)confirmTrashPurge([...recycleSelection]);});
